CREATE DATABASE IF NOT EXISTS ops_knowledge CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ops_knowledge;
CREATE TABLE IF NOT EXISTS knowledge_base (id BIGINT NOT NULL AUTO_INCREMENT,name VARCHAR(128) NOT NULL,description VARCHAR(1000),status VARCHAR(16) NOT NULL DEFAULT 'enable',create_by BIGINT NOT NULL,update_by BIGINT,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_knowledge_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS knowledge_document (id BIGINT NOT NULL AUTO_INCREMENT,knowledge_base_id BIGINT NOT NULL,file_name VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,file_type VARCHAR(16) NOT NULL,file_size BIGINT NOT NULL,storage_path VARCHAR(512) NOT NULL,status VARCHAR(32) NOT NULL,content_hash CHAR(64) NOT NULL,version INT NOT NULL DEFAULT 1,parse_error VARCHAR(1000),create_by BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),KEY idx_document_base_status_time(knowledge_base_id,status,create_time),KEY idx_document_hash(content_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS knowledge_chunk (id BIGINT NOT NULL AUTO_INCREMENT,document_id BIGINT NOT NULL,chunk_index INT NOT NULL,content MEDIUMTEXT NOT NULL,token_count INT,embedding_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',page_number INT,metadata_json JSON,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_chunk_document_index(document_id,chunk_index)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS document_parse_task (id BIGINT NOT NULL AUTO_INCREMENT,document_id BIGINT NOT NULL,status VARCHAR(32) NOT NULL,retry_count INT NOT NULL DEFAULT 0,next_retry_time DATETIME,error_message VARCHAR(1000),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_parse_status_retry(status,next_retry_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mq_consumed_event (id BIGINT NOT NULL AUTO_INCREMENT,consumer_name VARCHAR(128) NOT NULL,event_id CHAR(36) NOT NULL,consume_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_consumer_event(consumer_name,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
